  assert.deepEqual((await evaluate('window.__labReactionEvents.at(-1).products')),['ethyl-acetate','acetic-acid']);
  assert.deepEqual(await evaluate('window.__discoveryDialogCounts'),{labClose:1,labOpen:1,collectionOpen:1,collectionClose:1},'A two-species queue closes/reopens each canonical dialog exactly once.');
  const focusRestore=await evaluate("({valid:!!window.__focusBeforeDiscovery?.isConnected&&!window.__focusBeforeDiscovery?.disabled&&!window.__focusBeforeDiscovery?.closest?.('[inert]'),restored:document.activeElement===window.__focusBeforeDiscovery,fallback:document.activeElement===document.querySelector('[data-lab-close]')||document.activeElement===document.querySelector('#open-reaction-lab')})");assert.equal(focusRestore.restored||focusRestore.fallback,true,`Reaction Lab focus returns to the recorded target or stable fallback: ${JSON.stringify(focusRestore)}`);
