  assert.equal(browserErrors.length,0,`Browser reported errors: ${JSON.stringify(browserErrors)}`);
  console.log('Reaction Lab 390×844 browser regression passed: actual pointer reactions, canonical multi-product Discovery queue, duplicate-product dismissal, pause/resume, same-session Feed candidates, persistence and no replay.');
